<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\{Event,Endorser,PublicSubmission,Task}; use Illuminate\Http\Request;
class SearchController extends Controller { public function __invoke(Request $r){$q=trim((string)$r->query('q'));$like='%'.addcslashes($q,'%_\\').'%';$results=collect();if($q!==''){$results=$results->concat(Event::where(fn($x)=>$x->where('name','like',$like)->orWhere('venue','like',$like)->orWhere('contact_person','like',$like))->limit(10)->get()->map(fn($x)=>['type'=>'Event','title'=>$x->name,'meta'=>$x->event_date?->format('M j, Y').' · '.$x->venue,'url'=>route('admin.events.show',$x)]));$results=$results->concat(Endorser::where(fn($x)=>$x->where('name','like',$like)->orWhere('email','like',$like)->orWhere('contact_number','like',$like))->limit(10)->get()->map(fn($x)=>['type'=>'Endorser','title'=>$x->name,'meta'=>$x->email,'url'=>route('admin.endorsers.edit',$x)]));$results=$results->concat(PublicSubmission::where('data','like',$like)->limit(10)->get()->map(fn($x)=>['type'=>'Inquiry','title'=>$x->subject(),'meta'=>$x->referenceNumber(),'url'=>route('admin.inquiries.show',$x)]));$results=$results->concat(Task::where(fn($x)=>$x->where('title','like',$like)->orWhere('details','like',$like))->limit(10)->get()->map(fn($x)=>['type'=>'Task','title'=>$x->title,'meta'=>$x->task_date?->format('M j, Y'),'url'=>route('admin.tasks.index',['date'=>$x->task_date?->format('Y-m-d')]) ]));}return view('admin.search',compact('q','results'));}}
